import React, { useState, useRef, useEffect } from 'react';
import { Game } from './components/Game';
import { PillButton } from './components/PillButton';
import { Flow } from 'flow-sdk';
import { BIOMES } from './constants';
import { audio } from './services/AudioEngine';

export default function App() {
  const [gameState, setGameState] = useState<'idle' | 'playing' | 'gameover'>('idle');
  const [score, setScore] = useState(0);
  const [highScore, setHighScore] = useState(0);
  const [level, setLevel] = useState(1);
  const [lives, setLives] = useState(0);
  const [playerSkin, setPlayerSkin] = useState<string | null>(null);
  const [isMusicOn, setIsMusicOn] = useState(false);
  const gameRef = useRef<{ reset: () => void; snapshot: () => Promise<void> }>(null);

  useEffect(() => {
    audio.toggle(isMusicOn);
  }, [isMusicOn]);

  // Sync level changes with audio engine
  useEffect(() => {
    if (isMusicOn) {
      audio.setLevel(level);
    }
  }, [level, isMusicOn]);

  const handleStart = () => {
    setGameState('playing');
    setLevel(1);
    setScore(0);
    setLives(0);
    audio.setLevel(1);
    gameRef.current?.reset();
    if (!isMusicOn) setIsMusicOn(true);
  };

  const handleGameOver = (finalScore: number) => {
    setGameState('gameover');
    setScore(finalScore);
    if (finalScore > highScore) setHighScore(finalScore);
  };

  const handleLevelUpdate = (newLevel: number) => {
    if (newLevel > level) {
      // Award extra life for reaching a new level
      setLives(prev => prev + 1);
    }
    setLevel(newLevel);
  };

  const handleLifeLost = () => {
    setLives(prev => Math.max(0, prev - 1));
  };

  const handleSelectSkin = async () => {
    try {
      const media = await Flow.media.select({ filter: 'image' });
      if (media) {
        setPlayerSkin(`data:${media.mimeType};base64,${media.base64}`);
      }
    } catch (err) {
      console.error("Failed to select skin", err);
    }
  };

  const handleSnapshot = async () => {
    if (gameRef.current) {
      await gameRef.current.snapshot();
    }
  };

  const currentBiomeName = BIOMES[level - 1]?.name || BIOMES[BIOMES.length - 1].name;

  return (
    <div className="h-screen w-screen bg-[#050505] overflow-hidden flex flex-col items-center justify-center relative font-sans text-white">
      <div className="w-full h-full max-w-2xl relative shadow-[0_0_50px_rgba(0,255,255,0.1)] overflow-hidden border-x border-white/5 bg-black">
        <Game 
          ref={gameRef}
          onGameOver={handleGameOver} 
          onScoreUpdate={setScore}
          onLevelUpdate={handleLevelUpdate}
          onLifeLost={handleLifeLost}
          lives={lives}
          skinUrl={playerSkin}
          isPaused={gameState !== 'playing'}
        />

        {/* Global Controls */}
        <div className="absolute top-4 right-4 z-30 flex gap-2">
          <button 
            onClick={() => setIsMusicOn(!isMusicOn)}
            className="w-10 h-10 flex items-center justify-center rounded-full bg-black/60 backdrop-blur-md border border-white/10 hover:border-cyan-500/50 hover:bg-cyan-500/10 transition-all group"
          >
            <span className="material-symbols-outlined text-[20px] text-white group-hover:text-cyan-400">
              {isMusicOn ? 'volume_up' : 'volume_off'}
            </span>
          </button>
        </div>

        {/* Overlay UI */}
        {gameState === 'idle' && (
          <div className="absolute inset-0 z-20 flex flex-col items-center justify-center bg-black/80 backdrop-blur-md p-6 text-center">
            <div className="relative mb-8">
              <h1 className="text-6xl font-black italic tracking-tighter text-transparent bg-clip-text bg-gradient-to-b from-cyan-400 to-blue-600 drop-shadow-[0_0_15px_rgba(34,211,238,0.5)]">
                VOID VELOCITY
              </h1>
              <div className="absolute -bottom-2 left-0 w-full h-1 bg-cyan-500/30 scale-x-110 blur-sm"></div>
            </div>
            <p className="text-cyan-100/50 mb-8 max-w-sm font-medium tracking-wide uppercase text-[10px]">
              High-Speed Vertical Ascension Protocol // No Limits
            </p>
            <div className="flex flex-col gap-3 w-48">
              <PillButton variant="solid" onClick={handleStart}>
                INITIATE LAUNCH
              </PillButton>
              <PillButton variant="outline" onClick={handleSelectSkin} icon={<span className="material-symbols-outlined text-[18px]">palette</span>}>
                CUSTOM FRAME
              </PillButton>
            </div>
          </div>
        )}

        {gameState === 'gameover' && (
          <div className="absolute inset-0 z-20 flex flex-col items-center justify-center bg-black/90 backdrop-blur-xl p-6 text-center animate-in fade-in slide-in-from-bottom-8 duration-500">
            <h2 className="text-5xl font-black italic text-red-500 mb-1 skew-x-[-10deg]">SYSTEM CRASH</h2>
            <div className="my-6 relative py-4 px-8 border-y border-white/5 bg-white/5">
              <p className="text-white/30 text-[9px] uppercase tracking-[0.4em] mb-2 font-bold">Altitude Logged</p>
              <p className="text-6xl font-black text-white tabular-nums drop-shadow-lg">{score}<span className="text-xl text-white/30 ml-1">M</span></p>
            </div>
            {score >= highScore && score > 0 && (
              <p className="text-cyan-400 font-black italic mb-6 animate-pulse tracking-tighter">
                NEW SECTOR RECORD ACHIEVED
              </p>
            )}
            <div className="flex flex-col gap-3 w-48">
              <PillButton variant="solid" onClick={handleStart}>
                REBOOT SYSTEM
              </PillButton>
              <PillButton variant="outline" onClick={handleSnapshot} icon={<span className="material-symbols-outlined text-[18px]">download</span>}>
                LOG TELEMETRY
              </PillButton>
            </div>
          </div>
        )}

        {/* HUD - Left */}
        {gameState === 'playing' && (
          <div className="absolute top-4 left-4 z-10 flex flex-col gap-1 pointer-events-none">
            <div className="bg-black/60 backdrop-blur-md px-4 py-2 rounded-sm border-l-4 border-cyan-500 shadow-xl">
              <div className="flex items-center gap-2">
                <span className="material-symbols-outlined text-[14px] text-cyan-400 animate-pulse">speed</span>
                <span className="text-2xl font-black tabular-nums italic text-white">{score}<span className="text-xs opacity-50 ml-0.5">m</span></span>
              </div>
            </div>
            <p className="text-[9px] text-white/30 font-bold ml-1 uppercase tracking-widest italic">BEST: {highScore}M</p>
          </div>
        )}

        {/* HUD - Right (Lives & Sector) */}
        {gameState === 'playing' && (
          <div className="absolute top-4 right-16 z-10 pointer-events-none flex flex-col items-end gap-2">
            <div className="flex flex-col items-end bg-black/60 backdrop-blur-md px-4 py-2 rounded-sm border-r-4 border-cyan-500">
              <p className="text-[9px] font-black text-cyan-400/50 uppercase tracking-[0.2em] mb-0.5">Sector Info</p>
              <p className="text-2xl font-black text-white leading-none italic">S-{level}</p>
              <p className="text-[10px] text-white font-bold uppercase mt-1 tracking-wider bg-white/10 px-2 py-0.5">{currentBiomeName}</p>
            </div>

            <div className="bg-black/60 backdrop-blur-md px-3 py-1.5 rounded-sm border-r-4 border-red-500 flex items-center gap-2">
              <span className={`material-symbols-outlined text-[16px] ${lives <= 1 ? 'text-red-500 animate-pulse' : 'text-red-400'}`}>
                favorite
              </span>
              <span className="text-lg font-black italic text-white leading-none">x{lives}</span>
            </div>
          </div>
        )}

        {/* Instructions */}
        {gameState === 'playing' && (
          <div className="absolute bottom-4 left-1/2 -translate-x-1/2 z-10 text-cyan-400/40 text-[9px] font-black tracking-[0.3em] bg-black/40 px-6 py-2 rounded-full border border-white/5 backdrop-blur-sm">
            CONTROL: [A][D] | [←][→] | MOUSE
          </div>
        )}
      </div>
    </div>
  );
}

import React, { useRef, useEffect, useImperativeHandle, forwardRef } from 'react';
import p5 from 'p5@1.11.3';
import { Flow } from 'flow-sdk';
import { BIOMES } from '../constants';

interface GameProps {
  onGameOver: (score: number) => void;
  onScoreUpdate: (score: number) => void;
  onLevelUpdate: (level: number) => void;
  onLifeLost: () => void;
  lives: number;
  skinUrl: string | null;
  isPaused: boolean;
}

export interface GameHandle {
  reset: () => void;
  snapshot: () => Promise<void>;
}

export const Game = forwardRef<GameHandle, GameProps>(({ onGameOver, onScoreUpdate, onLevelUpdate, onLifeLost, lives, skinUrl, isPaused }, ref) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const sketchRef = useRef<p5 | null>(null);
  const propsRef = useRef({ onGameOver, onScoreUpdate, onLevelUpdate, onLifeLost, lives, skinUrl, isPaused });

  useEffect(() => {
    propsRef.current = { onGameOver, onScoreUpdate, onLevelUpdate, onLifeLost, lives, skinUrl, isPaused };
  }, [onGameOver, onScoreUpdate, onLevelUpdate, onLifeLost, lives, skinUrl, isPaused]);

  useImperativeHandle(ref, () => ({
    reset: () => {
      if (sketchRef.current) (sketchRef.current as any).resetGame();
    },
    snapshot: async () => {
      const canvas = containerRef.current?.querySelector('canvas');
      if (canvas) {
        const base64 = canvas.toDataURL('image/png').split(',')[1];
        await Flow.download({
          base64,
          mimeType: 'image/png',
          filename: `Void_Velocity_Telemetry_${Date.now()}.png`
        });
      }
    }
  }));

  useEffect(() => {
    const sketch = (p: p5) => {
      let player: Player;
      let platforms: Platform[] = [];
      let particles: Particle[] = [];
      let score = 0;
      let viewY = 0;
      let skinImg: p5.Image | null = null;
      let currentBiome = BIOMES[0];
      let level = 1;
      let transitionAlpha = 0;

      p.preload = () => {
        if (propsRef.current.skinUrl) {
          skinImg = p.loadImage(propsRef.current.skinUrl);
        }
      };

      p.setup = () => {
        const container = containerRef.current!;
        p.createCanvas(container.clientWidth, container.clientHeight);
        initGame();
      };

      const initGame = () => {
        player = new Player(p.width / 2, p.height - 100);
        platforms = [];
        particles = [];
        score = 0;
        viewY = 0;
        level = 1;
        currentBiome = BIOMES[0];

        // Initial jump distance calculation: height = v^2 / 2g
        // With jumpForce = -14 and gravity = 0.45, max height is ~217px.
        // 80% of that is ~174px.
        const baseSpacing = 174;

        for (let i = 0; i < 10; i++) {
          const y = p.height - i * baseSpacing;
          platforms.push(new Platform(p, p.random(50, p.width - 50), y, 0));
        }
        platforms[0] = new Platform(p, p.width / 2, p.height - 50, 0, 'static');
      };

      (p as any).resetGame = initGame;

      p.draw = () => {
        if (propsRef.current.isPaused) return;

        updateLevel();
        drawOpticalIllusionBackground();

        const targetViewY = player.y - p.height * 0.6;
        viewY = p.lerp(viewY, targetViewY, 0.1);

        p.push();
        p.translate(0, -viewY);

        // Platforms
        for (let i = platforms.length - 1; i >= 0; i--) {
          const plat = platforms[i];
          plat.update(p);

          if (!plat.isHidden) {
            plat.display(p, currentBiome);

            if (player.dy > 0 && player.collidesWith(plat)) {
              if (plat.type === 'vanishing') {
                if (plat.alpha < 80) continue;
                plat.triggerVanish();
              }

              if (plat.type === 'breaking') {
                plat.triggerBreak();
              }

              const jumpPower = plat.type === 'bouncy' ? player.jumpForce * 1.6 : player.jumpForce;
              player.jump(jumpPower);
              spawnParticles(player.x, player.y + player.h/2, plat.type === 'bouncy' ? '#ffff00' : (plat.type === 'breaking' ? '#ff0000' : currentBiome.particleColor));
            }
          } else {
            plat.display(p, currentBiome); 
          }

          if (plat.y > viewY + p.height + 300) {
            platforms.splice(i, 1);
            spawnNextPlatform();
          }
        }

        // Particles
        for (let i = particles.length - 1; i >= 0; i--) {
          particles[i].update();
          particles[i].display(p);
          if (particles[i].isDead()) particles.splice(i, 1);
        }

        player.update(p);
        player.display(p, skinImg, currentBiome);

        p.pop();

        if (transitionAlpha > 0) {
          p.fill(255, transitionAlpha);
          p.noStroke();
          p.rect(0, 0, p.width, p.height);
          transitionAlpha -= 10;
        }

        // Fall handling
        if (player.y > viewY + p.height + 150) {
          if (propsRef.current.lives > 0) {
            player.respawn(platforms);
            propsRef.current.onLifeLost();
            transitionAlpha = 150; 
          } else {
            propsRef.current.onGameOver(score);
          }
        }
      };

      const spawnNextPlatform = () => {
        const highestY = platforms.reduce((min, plat) => Math.min(min, plat.y), 0);

        // Calculate physics-based spacing
        const jumpHeight = Math.pow(player.jumpForce, 2) / (2 * player.gravity);
        const targetSpacing = jumpHeight * 0.8;

        // Add minimal variance to keep it predictable but arcade-like
        const spacing = p.random(targetSpacing * 0.95, targetSpacing * 1.05);
        const y = highestY - spacing;
        const x = p.random(60, p.width - 60);

        const diff = currentBiome.difficulty;
        platforms.push(new Platform(p, x, y, diff));
        score = Math.max(score, Math.floor(-player.y / 10 + 70));
        propsRef.current.onScoreUpdate(score);
      };

      const updateLevel = () => {
        const newLevel = Math.min(BIOMES.length, Math.floor(score / 100) + 1);
        if (newLevel !== level) {
          level = newLevel;
          currentBiome = BIOMES[level - 1];
          propsRef.current.onLevelUpdate(level);
          transitionAlpha = 255;
        }
      };

      const drawOpticalIllusionBackground = () => {
        p.background(currentBiome.bgBottom);
        const time = p.frameCount * 0.01;
        const centerX = p.width / 2;
        const centerY = p.height / 2;

        p.push();
        p.noFill();
        p.strokeWeight(1);

        const patternType = (level - 1) % 4;

        if (patternType === 0) {
          for (let i = 0; i < 20; i++) {
            const r = (i * 40 + p.frameCount * 2) % 800;
            const alpha = p.map(r, 0, 800, 150, 0);
            p.stroke(p.color(currentBiome.platColor + p.hex(Math.floor(alpha), 2)));
            p.ellipse(centerX, centerY + (viewY * 0.1), r, r);
          }
        } else if (patternType === 1) {
          p.translate(centerX, centerY);
          p.rotate(time * 0.2);
          p.stroke(p.color(currentBiome.platColor + '44'));
          for (let i = -p.width; i < p.width; i += 20) {
            p.line(i, -p.height, i, p.height);
          }
        } else if (patternType === 2) {
          p.rectMode(p.CENTER);
          for (let i = 0; i < 15; i++) {
            const size = (i * 60 + p.frameCount * 3) % 900;
            const alpha = p.map(size, 0, 900, 100, 0);
            p.stroke(p.color(currentBiome.platColor + p.hex(Math.floor(alpha), 2)));
            p.push();
            p.translate(centerX, centerY);
            p.rotate(p.sin(time + i) * 0.5);
            p.rect(0, 0, size, size);
            p.pop();
          }
        } else {
          p.strokeWeight(2);
          for (let i = 0; i < 360; i += 20) {
            const angle = p.radians(i);
            const rBase = 200 + p.sin(time * 5 + i * 0.1) * 100;
            const x1 = centerX + p.cos(angle) * rBase;
            const y1 = centerY + p.sin(angle) * rBase;
            p.stroke(p.color(currentBiome.platColor + '33'));
            p.line(centerX, centerY, x1, y1);
          }
        }
        p.pop();
      };

      const spawnParticles = (x: number, y: number, color: string) => {
        for(let i = 0; i < 10; i++) particles.push(new Particle(x, y, color));
      };

      class Player {
        x: number; y: number; w: number; h: number;
        dx: number; dy: number;
        gravity: number; jumpForce: number; speed: number;
        trail: {x: number, y: number}[];
        invincibility: number = 0;

        constructor(x: number, y: number) {
          this.x = x; this.y = y; this.w = 24; this.h = 24;
          this.dx = 0; this.dy = 0;
          this.gravity = 0.45;
          this.jumpForce = -14.0;
          this.speed = 7.5;
          this.trail = [];
        }

        respawn(platforms: Platform[]) {
          // Prioritize non-hazardous, solid platforms for respawn
          let safePlats = platforms.filter(p => 
            p.type !== 'breaking' && 
            p.type !== 'vanishing' && 
            !p.isHidden && 
            p.y < viewY + p.height // Must be on screen
          );

          if (safePlats.length === 0) {
            safePlats = platforms.filter(p => !p.isHidden);
          }

          // Find the highest available safe platform
          const target = safePlats.reduce((acc, curr) => (curr.y < acc.y ? curr : acc), safePlats[0] || platforms[0]);

          this.x = target.x;
          this.y = target.y - this.h; // Position exactly on the platform
          this.dx = 0;
          this.dy = 0;
          this.invincibility = 120; // Slightly longer invincibility for recovery
          this.trail = [];
        }

        update(p: p5) {
          const moveL = p.keyIsDown(p.LEFT_ARROW) || p.keyIsDown(65) || (p.mouseIsPressed && p.mouseX < p.width/2);
          const moveR = p.keyIsDown(p.RIGHT_ARROW) || p.keyIsDown(68) || (p.mouseIsPressed && p.mouseX >= p.width/2);

          if (moveL) this.dx = -this.speed;
          else if (moveR) this.dx = this.speed;
          else this.dx *= 0.85;

          this.x += this.dx;
          this.dy += this.gravity;
          this.y += this.dy;

          if (this.x < 0) this.x = p.width;
          if (this.x > p.width) this.x = 0;

          if (this.invincibility > 0) this.invincibility--;

          this.trail.push({x: this.x, y: this.y});
          if (this.trail.length > 15) this.trail.shift();
        }

        display(p: p5, skin: p5.Image | null, biome: any) {
          if (this.invincibility > 0 && p.frameCount % 6 < 3) return;

          p.strokeWeight(4);
          for (let i = 0; i < this.trail.length - 1; i++) {
            const alpha = p.map(i, 0, this.trail.length, 0, 200);
            p.stroke(p.color(biome.playerColor + p.hex(Math.floor(alpha), 2)));
            p.line(this.trail[i].x, this.trail[i].y, this.trail[i+1].x, this.trail[i+1].y);
          }

          p.push();
          p.translate(this.x, this.y);
          p.rotate(this.dx * 0.1);

          if (skin) {
            p.imageMode(p.CENTER);
            p.image(skin, 0, 0, this.w * 1.5, this.h * 1.5);
          } else {
            p.noStroke();
            p.fill(255);
            p.rectMode(p.CENTER);
            p.rect(0, 0, this.w, this.h, 4);
            p.fill(biome.playerColor);
            p.rect(0, 0, this.w * 0.7, this.h * 0.7, 2);
          }
          p.pop();
        }

        jump(force?: number) { this.dy = force || this.jumpForce; }

        collidesWith(plat: Platform) {
          if (this.invincibility > 80) return false; // More grace period after respawn
          return (
            this.dy > 0 &&
            this.x + this.w/2 > plat.x - plat.w/2 &&
            this.x - this.w/2 < plat.x + plat.w/2 &&
            this.y + this.h/2 > plat.y - plat.h/2 &&
            this.y + this.h/2 < plat.y + plat.h/2 + 15
          );
        }
      }

      class Platform {
        x: number; y: number; w: number; h: number;
        type: 'static' | 'moving' | 'breaking' | 'bouncy' | 'vanishing';
        moveDir: number; moveRange: number; startX: number;
        alpha: number; alphaDir: number;

        isHidden: boolean = false;
        respawnTimer: number = 0;

        constructor(p: p5, x: number, y: number, difficulty: number, forceType?: any) {
          this.x = x; this.y = y; this.startX = x;
          this.h = 10;
          this.w = 120;
          this.alpha = 255;
          this.alphaDir = -4 - difficulty;

          if (forceType) {
            this.type = forceType;
          } else {
            const r = p.random(100);
            if (difficulty >= 1 && r > 75) this.type = 'moving';
            else if (difficulty >= 2 && r > 60) this.type = 'breaking';
            else if (difficulty >= 3 && r > 45) this.type = 'bouncy';
            else if (difficulty >= 4 && r > 35) this.type = 'vanishing';
            else this.type = 'static';
          }

          this.moveDir = p.random() > 0.5 ? 1 : -1;
          this.moveRange = p.random(40, 100 + difficulty * 15);
        }

        triggerVanish() {
          if (!this.isHidden) {
            this.isHidden = true;
            this.respawnTimer = 180;
          }
        }

        triggerBreak() {
          if (!this.isHidden) {
            this.isHidden = true;
            this.respawnTimer = 180;
          }
        }

        update(p: p5) {
          if (this.type === 'moving') {
            this.x = this.startX + p.sin(p.frameCount * 0.08) * this.moveRange;
          }

          if (this.isHidden) {
            this.respawnTimer--;
            if (this.respawnTimer < 40) {
              this.alpha = (this.respawnTimer % 6 < 3) ? 100 : 0;
            } else {
              this.alpha = 0;
            }

            if (this.respawnTimer <= 0) {
              this.isHidden = false;
              this.alpha = 255;
            }
          } else if (this.type === 'vanishing') {
            this.alpha += this.alphaDir;
            if (this.alpha <= 0 || this.alpha >= 255) this.alphaDir *= -1;
          }
        }

        display(p: p5, biome: any) {
          if (this.isHidden && this.alpha === 0) return;

          p.push();
          p.translate(this.x, this.y);
          p.noStroke();
          p.rectMode(p.CENTER);

          let col = biome.platColor;
          if (this.type === 'breaking') col = '#ff0000';
          if (this.type === 'bouncy') col = '#00ff00';
          if (this.type === 'vanishing') col = '#ffffff';

          const c = p.color(col);
          c.setAlpha(this.alpha);

          p.fill(p.red(c), p.green(c), p.blue(c), this.alpha * 0.2);
          p.rect(0, 0, this.w + 10, this.h + 6, 2);
          p.fill(c);

          if (this.type === 'breaking' && p.random() > 0.95) {
            p.translate(p.random(-2, 2), 0);
          }

          p.rect(0, 0, this.w, this.h, 1);

          if (this.type === 'bouncy') {
            p.fill(0);
            p.rect(0, -3, this.w * 0.8, 2);
          }
          p.pop();
        }
      }

      class Particle {
        x: number; y: number; vx: number; vy: number; life: number; color: string;
        constructor(x: number, y: number, color: string) {
          this.x = x; this.y = y;
          this.vx = p.random(-5, 5); this.vy = p.random(-2, 6);
          this.life = 255; this.color = color;
        }
        update() { this.x += this.vx; this.y += this.vy; this.life -= 15; }
        display(p: p5) {
          p.noStroke();
          const c = p.color(this.color);
          c.setAlpha(this.life);
          p.fill(c);
          p.rect(this.x, this.y, 4, 4);
        }
        isDead() { return this.life <= 0; }
      }
    };

    const inst = new p5(sketch, containerRef.current!);
    sketchRef.current = inst;
    return () => inst.remove();
  }, [skinUrl]);

  return <div ref={containerRef} className="w-full h-full cursor-pointer touch-none" />;
});

import React from 'react';

interface PillButtonProps {
  icon?: React.ReactNode;
  children: React.ReactNode;
  variant?: 'filled' | 'outline' | 'solid';
  onClick?: () => void;
  disabled?: boolean;
}

export const PillButton: React.FC<PillButtonProps> = ({ 
  icon, 
  children, 
  variant = 'filled', 
  onClick,
  disabled = false
}) => {
  const base = 'flex items-center gap-[6px] justify-center w-full h-[40px] rounded-xl font-medium tracking-[0.1px] transition-all cursor-pointer disabled:opacity-50 disabled:cursor-not-allowed active:scale-95';

  const variants: Record<string, string> = {
    filled: 'bg-[#969696] hover:bg-[#a6a6a6] active:bg-[#868686] text-black text-[13px] px-4 select-none',
    outline: 'border border-[#595959] hover:bg-white/5 active:bg-white/10 backdrop-blur-[40px] text-[13px] px-4 text-white select-none',
    solid: 'bg-white hover:bg-gray-200 active:bg-gray-300 text-black text-[13px] px-4 select-none',
  };

  return (
    <button 
      className={`${base} ${variants[variant]}`} 
      onClick={onClick}
      disabled={disabled}
    >
      {icon && <span className="flex items-center justify-center">{icon}</span>}
      <span>{children}</span>
    </button>
  );
};

/**
 * Procedural "Rage" engine for Void Velocity.
 * Replaces rave techno with aggressive, distorted, high-intensity soundscapes.
 */
export class AudioEngine {
  private ctx: AudioContext | null = null;
  private isStarted = false;
  private loopId: number | null = null;
  private level = 1;

  start() {
    if (this.isStarted) return;

    this.ctx = new (window.AudioContext || (window as any).webkitAudioContext)();
    this.isStarted = true;
    this.playLoop();
  }

  setLevel(level: number) {
    this.level = level;
  }

  private playBeat(time: number, freq: number, type: OscillatorType, vol: number, decay = 0.2, filterFreq = 1000, distortion = false) {
    if (!this.ctx) return;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    const filter = this.ctx.createBiquadFilter();

    osc.type = type;
    osc.frequency.setValueAtTime(freq, time);

    // Aggressive pitch drop for that "rage" punch
    osc.frequency.exponentialRampToValueAtTime(freq * 0.01, time + decay);

    filter.type = distortion ? 'bandpass' : 'lowpass';
    filter.frequency.setValueAtTime(filterFreq, time);
    filter.Q.setValueAtTime(distortion ? 15 : 1, time);

    // Boost gain to naturally distort if requested (rage mode)
    const finalVol = distortion ? vol * 1.5 : vol;
    gain.gain.setValueAtTime(finalVol, time);
    gain.gain.exponentialRampToValueAtTime(0.001, time + decay);

    osc.connect(filter);
    filter.connect(gain);
    gain.connect(this.ctx.destination);

    osc.start(time);
    osc.stop(time + decay);
  }

  private playRageBass(time: number, freq: number, duration: number, vol: number) {
    if (!this.ctx) return;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    const filter = this.ctx.createBiquadFilter();

    osc.type = 'sawtooth';
    osc.frequency.setValueAtTime(freq, time);
    osc.frequency.linearRampToValueAtTime(freq * 0.8, time + duration);

    filter.type = 'lowpass';
    filter.frequency.setValueAtTime(400 + Math.random() * 600, time);
    filter.Q.setValueAtTime(10, time);

    gain.gain.setValueAtTime(0, time);
    gain.gain.linearRampToValueAtTime(vol, time + 0.05);
    gain.gain.linearRampToValueAtTime(0, time + duration);

    osc.connect(filter);
    filter.connect(gain);
    gain.connect(this.ctx.destination);

    osc.start(time);
    osc.stop(time + duration);
  }

  private playLoop() {
    if (!this.ctx || !this.isStarted) return;

    const schedule = () => {
      if (!this.ctx || !this.isStarted) return;

      const startTime = this.ctx.currentTime + 0.1;
      // Faster, more aggressive tempo
      const bpm = 175 + (this.level * 4);
      const beatDuration = 60 / bpm; 

      for (let i = 0; i < 16; i++) {
        const t = startTime + i * (beatDuration * 0.25); // 16th notes

        // --- HARD KICK ---
        if (i % 4 === 0) {
          this.playBeat(t, 60, 'square', 0.8, 0.15, 400, true);
        }

        // --- RAGE BASS ---
        if (i % 8 === 0 || i % 8 === 3 || i % 8 === 6) {
          const bassFreq = [40, 45, 35, 50][Math.floor(this.level / 2) % 4];
          this.playRageBass(t, bassFreq, beatDuration * 0.4, 0.2);
        }

        // --- SNARE / NOISE CLAP ---
        if (i % 8 === 4) {
          this.playBeat(t, 2000, 'sawtooth', 0.3, 0.08, 3000, true);
        }

        // --- GLITCH ARP ---
        const patternSeed = (this.level + i) % 7;
        if (patternSeed === 0 || patternSeed === 3) {
          const arpFreq = 200 + (this.level * 20) + (i * 50);
          this.playBeat(t, arpFreq, 'sawtooth', 0.05, 0.05, 2000, true);
        }

        // High sector chaos
        if (this.level > 3 && i % 2 === 1 && Math.random() > 0.7) {
          this.playBeat(t, 8000, 'square', 0.02, 0.01, 10000);
        }
      }

      this.loopId = window.setTimeout(schedule, (beatDuration * 4) * 1000);
    };

    schedule();
  }

  stop() {
    if (this.loopId) clearTimeout(this.loopId);
    if (!this.ctx) return;
    this.ctx.close();
    this.ctx = null;
    this.isStarted = false;
  }

  toggle(playing: boolean) {
    if (playing) {
      if (this.ctx?.state === 'suspended') {
        this.ctx.resume();
      } else {
        this.start();
      }
    } else {
      this.ctx?.suspend();
    }
  }
}

export const audio = new AudioEngine();
